<template><div class="card max-w-md mx-auto space-y-4"><h1 class="text-2xl font-bold">Create your account</h1><form @submit.prevent="submit" class="space-y-4"><div><label>Display name</label><input v-model.trim="name" maxlength="80" required/></div><div><label>Email</label><input type="email" v-model.trim="email" required autocomplete="email"/></div><div><label>Password (at least 8 characters)</label><input type="password" minlength="8" v-model="password" required autocomplete="new-password"/></div><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="message" class="text-green-800">{{message}}</p><button class="btn w-full" :disabled="busy">{{busy?'Please wait…':'Register'}}</button></form><NuxtLink to="/auth/login" class="text-red-800 underline">Already registered?</NuxtLink></div></template>
<script setup lang="ts">
const client=useSupabaseClient(),name=ref(''),email=ref(''),password=ref(''),error=ref(''),message=ref(''),busy=ref(false)
async function submit(){busy.value=true;error.value='';message.value='';try{const {data,error:e}=await client.auth.signUp({email:email.value,password:password.value,options:{data:{display_name:name.value}}});if(e)throw e;if(data.session)await navigateTo('/recipes');else message.value='Check your email to confirm your account, then sign in.'}catch(e:any){error.value=e.message||'Unable to register'}finally{busy.value=false}}
</script>
